// Behavioral cli tests.
#[test] fn playback_is_explicit_and_requires_html_output() {let o=Options::parse(["--steps","--output","demo.html"].into_iter().map(str::to_string)).unwrap();assert!(o.steps);let p=std::process::Command::new(env!("CARGO_BIN_EXE_rusty-voronoi")).args(["--steps","--output","-"]).output().unwrap();assert!(!p.status.success());assert!(String::from_utf8_lossy(&p.stderr).contains("HTML"));}
#[test] fn relaxation_option_reaches_the_executable() {use std::process::Command;let o=Options::parse(["--relax","2"].into_iter().map(str::to_string)).unwrap();assert_eq!(o.relax,2);let p=Command::new(env!("CARGO_BIN_EXE_rusty-voronoi")).args(["--count","4","--relax","2","--output","-"]).output().unwrap();assert!(p.status.success());assert!(p.stdout.starts_with(b"<svg "));assert!(Options::parse(["--relax","101"].into_iter().map(str::to_string)).is_err());}
#[test] fn binary_help_and_stdout_svg_work() {use std::process::Command;let exe=env!("CARGO_BIN_EXE_rusty-voronoi");let help=Command::new(exe).arg("--help").output().unwrap();assert!(help.status.success());assert!(String::from_utf8_lossy(&help.stdout).contains("Usage:"));let out=Command::new(exe).args(["--count","3","--seed","5","--algorithm","fortune","--output","-"]).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));assert!(out.stdout.starts_with(b"<svg "));}
#[test] fn parse_sites_accepts_comments_and_reports_bad_rows() {let p=parse_sites("# sample\n2,3\n\n4 5 # second\n").unwrap();assert_eq!(p.len(),2);assert_eq!(p[1].x,4.);assert!(parse_sites("1,2,3").is_err());assert!(parse_sites("NaN,1").is_err());let o=Options::parse(["--sites","points.csv"].into_iter().map(str::to_string)).unwrap();assert_eq!(o.sites.as_deref(),Some("points.csv"));}
#[test] fn seeded_points_are_repeatable_and_in_bounds() {use rusty_voronoi::geometry::Bounds;let b=Bounds::new(-2.,-1.,3.,8.).unwrap();let a=random_sites(25,42,b);assert_eq!(a,random_sites(25,42,b));assert_ne!(a,random_sites(25,43,b));assert!(a.iter().all(|p|b.contains(*p)));assert!(random_sites(0,1,b).is_empty());let o=Options::parse(["--count","12","--seed","42"].into_iter().map(str::to_string)).unwrap();assert_eq!(o.count,12);assert_eq!(o.seed,42);}
use rusty_voronoi::cli::*;
#[test] fn parse_viewport_algorithm_and_help() {let o=Options::parse(["--width","320","--height","240","--algorithm","fortune","--output","cells.svg","--labels"].into_iter().map(str::to_string)).unwrap();assert_eq!((o.width,o.height),(320,240));assert_eq!(o.algorithm,"fortune");assert!(o.labels);assert!(Options::parse(["--help".into()]).unwrap().help);assert!(help().contains("Usage:"));assert!(Options::parse(["--wat".into()]).is_err());}
